func (s *Service) startReviewRound(ctx *axi.Context, db *store.DB, home string, project store.Project, change store.Task, profile, name string) error {
	if project.IsDirectory() {
		return axi.Failure("review_round_unsupported", "directory Tasks cannot be reviewed as Git rounds", false)
	}
	if change.Type != "change" {
		return axi.Failure("review_round_target_invalid", "Review Rounds require a Change Task", false)
	}
	plan, err := change.AdmittedPlan()
	if err != nil {
		return admittedPlanFailure(err)
	}
	candidateReview := plan != nil && (plan.Review == "full-pipeline" || workspaceHasFullPipeline(plan))
	if candidateReview {
		pendingRefresh, err := db.OutstandingValidationFixHead(ctx.Context, change.ID, "freshness")
		if err != nil {
			return err
		}
		if pendingRefresh != "" {
			return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(change.Seq)}, {Key: "state", Value: "refresh_queued"}, {Key: "help", Value: []any{"The target-refresh instruction is already in flight; wait for the Worker's next done Signal before starting Review"}}})
		}
		if change.State != store.StateWorking && change.State != store.StateStalled && change.State != store.StateDone && change.State != store.StateMerging {
			return axi.Failure("review_target_incomplete", "Change Task must be active before its private candidate can be reviewed", false, "Answer the Worker with `posse send "+taskIDString(change.Seq)+"`; a full-pipeline Worker requests Review with `posse signal done` after submitting its private candidates")
		}
		if err := s.prepareReviewCandidateCheckouts(ctx.Context, db, home, project, change, plan); err != nil {
			var failure *axi.Error
			if errors.As(err, &failure) && failure.Code == "candidate_target_moved" {
				return s.queueReviewTargetRefresh(ctx, db, project, change)
			}
			return err
		}
	} else if err := reviewableChange(change); err != nil {
		return err
	}
	plan, err = change.AdmittedPlan()
	if err != nil {
		return admittedPlanFailure(err)
	}
	if plan == nil || plan.ValidationLoops == nil || !plan.ValidationLoops.Review.Enabled {
		return axi.Failure("review_loop_disabled", "Change Task "+taskIDString(change.Seq)+" has no enabled, frozen Review Loop", false)
	}
	maxRounds := plan.ValidationLoops.MaxReviewRounds()
	if maxRounds < 1 || maxRounds > 3 {
		return axi.Failure("plan_invalid", "Change Task has an invalid frozen Review Round cap", false)
	}
	if plan.ValidationLoops.ReviewParallel == "greenhouse" {
		targets, err := changeCandidateTargets(ctx.Context, db, project, change)
		if err != nil {
			return err
		}
		if err := s.startParallelGreenhouseReviews(ctx.Context, db, home, project, change, targets); err != nil {
			return err
		}
	}
	if profile == "" {
		profile, err = s.autoStartReviewProfile(ctx.Context, project, home)
		if err != nil {
			return err
		}
	}
	generated, err := buildReviewRound(ctx.Context, db, project, change, *plan, maxRounds, home)
	if err != nil {
		return err
	}
	if name == "" {
		name = fmt.Sprintf("review-round-%d", generated.Admission.Round)
	}
	if err := validateWorkerName(name); err != nil {
		return invalidWorkerNameFailure(name, err)
	}
	args := []string{"--name", name}
	if profile != "" {
		args = append(args, "--profile", profile)
	}
	err = s.spawnTask(ctx, args, generated)
	var failure *axi.Error
	if errors.As(err, &failure) && failure.Code == "review_round_cap" {
		usage, usageErr := db.ReviewCapUsage(ctx.Context, change.ID)
		if usageErr != nil {
			return usageErr
		}
		used := reviewCapUsed(change, usage)
		binding, headErr := reviewCapHead(ctx.Context, db, project, change)
		if headErr != nil {
			return headErr
		}
		if noticeErr := s.raiseReviewCapNotice(ctx.Context, db, project, change, binding, used, maxRounds); noticeErr != nil {
			return noticeErr
		}
		return axi.Failure("review_round_cap", fmt.Sprintf("frozen Review and repair cap reached at %s (%d of %d rounds used)", binding.label(), used, maxRounds), false, "Wait for the User's `review_cap` Decision")
	}
	return err
}

