1: package app
2: 
3: import (
4: 	"encoding/json"
5: 	"errors"
6: 	"os"
7: 	"path/filepath"
8: 	"syscall"
9: 
10: 	"github.com/thanhbinh1905/posse/internal/atomicfile"
11: )
12: 
13: type parallelReviewAction string
14: 
15: const (
16: 	parallelReviewSkip   parallelReviewAction = "skip"
17: 	parallelReviewStart  parallelReviewAction = "start"
18: 	parallelReviewResume parallelReviewAction = "resume"
19: )
20: 
21: type parallelReviewOwner struct {
22: 	PID         int    `json:"pid"`
23: 	Head        string `json:"head"`
24: 	RequestedAt int64  `json:"requested_at"`
25: }
26: 
27: func nextParallelReviewAction(hasVerdict, hasPending bool) parallelReviewAction {
28: 	if hasPending {
29: 		return parallelReviewResume
30: 	}
31: 	if hasVerdict {
32: 		return parallelReviewSkip
33: 	}
34: 	return parallelReviewStart
35: }
36: 
37: func parallelReviewLockPath(roundDir, repository string) string {
38: 	return filepath.Join(roundDir, repository+".parallel.lock")
39: }
40: 
41: func parallelReviewOwnerPath(roundDir, repository string) string {
42: 	return filepath.Join(roundDir, repository+".parallel-owner.json")
43: }
44: 
45: func parallelRequestMetadata(head string, requestedAt int64, hasPending bool, owner *parallelReviewOwner) (string, int64) {
46: 	if hasPending && owner != nil {
47: 		if owner.Head != "" {
48: 			head = owner.Head
49: 		}
50: 		if owner.RequestedAt > 0 {
51: 			requestedAt = owner.RequestedAt
52: 		}
53: 	}
54: 	return head, requestedAt
55: }
56: 
57: func acquireParallelReviewLock(path string) (*os.File, bool, error) {
58: 	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
59: 		return nil, false, err
60: 	}
61: 	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
62: 	if err != nil {
63: 		return nil, false, err
64: 	}
65: 	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
66: 		_ = file.Close()
67: 		if errors.Is(err, syscall.EWOULDBLOCK) {
68: 			return nil, true, nil
69: 		}
70: 		return nil, false, err
71: 	}
72: 	return file, false, nil
73: }
74: 
75: func inheritedParallelReviewLock(fd int, path string) (*os.File, error) {
76: 	file := os.NewFile(uintptr(fd), path)
77: 	if file == nil {
78: 		return nil, errors.New("invalid inherited parallel review lock")
79: 	}
80: 	fileInfo, err := file.Stat()
81: 	if err != nil {
82: 		_ = file.Close()
83: 		return nil, err
84: 	}
85: 	pathInfo, err := os.Stat(path)
86: 	if err != nil || !os.SameFile(fileInfo, pathInfo) {
87: 		_ = file.Close()
88: 		return nil, errors.New("inherited parallel review lock does not match its path")
89: 	}
90: 	return file, nil
91: }
92: 
93: func parallelReviewInFlight(path string) (bool, error) {
94: 	file, busy, err := acquireParallelReviewLock(path)
95: 	if err != nil || busy {
96: 		return busy, err
97: 	}
98: 	return false, releaseParallelReviewLock(file)
99: }
100: 
101: func releaseParallelReviewLock(file *os.File) error {
102: 	if file == nil {
103: 		return nil
104: 	}
105: 	unlockErr := syscall.Flock(int(file.Fd()), syscall.LOCK_UN)
106: 	closeErr := file.Close()
107: 	return errors.Join(unlockErr, closeErr)
108: }
109: 
110: func readParallelReviewOwner(path string) (*parallelReviewOwner, error) {
111: 	data, err := os.ReadFile(path)
112: 	if errors.Is(err, os.ErrNotExist) {
113: 		return nil, nil
114: 	}
115: 	if err != nil {
116: 		return nil, err
117: 	}
118: 	var owner parallelReviewOwner
119: 	if err := json.Unmarshal(data, &owner); err != nil {
120: 		return nil, err
121: 	}
122: 	if owner.PID < 2 || owner.Head == "" {
123: 		return nil, errors.New("invalid parallel review owner")
124: 	}
125: 	return &owner, nil
126: }
127: 
128: func writeParallelReviewOwner(path string, owner parallelReviewOwner) error {
129: 	data, err := json.Marshal(owner)
130: 	if err != nil {
131: 		return err
132: 	}
133: 	return atomicfile.Write(path, data, 0o600)
134: }
135: 
136: func clearParallelReviewOwner(path, pending string, pid int) error {
137: 	owner, err := readParallelReviewOwner(path)
138: 	if err != nil || owner == nil || owner.PID != pid {
139: 		return err
140: 	}
141: 	if _, err := os.Stat(pending); err == nil {
142: 		return nil
143: 	} else if !errors.Is(err, os.ErrNotExist) {
144: 		return err
145: 	}
146: 	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
147: 		return err
148: 	}
149: 	return nil
150: }
