987: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
988: 				return recordErr
989: 			}
990: 			continue
991: 		}
992: 		args := []string{"_greenhouse", "review", taskIDString(change.Seq), "--parallel-owner", ownerPath, "--parallel-lock-fd", "3"}
993: 		if project.IsWorkspace() {
994: 			args = append(args, "--repo", target.Repository)
995: 		}
996: 		command := exec.Command(binary, args...)
997: 		command.Dir = project.Root
998: 		command.Env = os.Environ()
999: 		command.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
1000: 		command.ExtraFiles = []*os.File{lock}
1001: 		logDir := filepath.Join(home, "projects", project.Name, "tasks", taskIDString(change.Seq), "greenhouse")
1002: 		if err := os.MkdirAll(logDir, 0o700); err != nil {
1003: 			_ = releaseParallelReviewLock(lock)
1004: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
1005: 				return recordErr
1006: 			}
1007: 			continue
1008: 		}
1009: 		log, err := os.OpenFile(filepath.Join(logDir, target.Repository+".parallel.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
