+			_ = releaseParallelReviewLock(lock)
+			if recordErr := recordFailure(err.Error()); recordErr != nil {
+				return recordErr
+			}
+			continue
+		}
+		args := []string{"_greenhouse", "review", taskIDString(change.Seq), "--parallel-owner", ownerPath, "--parallel-lock-fd", "3"}
