306: func builtinReviewLatency(ctx context.Context, db *store.DB, projectID int64) (*int64, error) {
307: 	rows, err := db.QueryContext(ctx, `SELECT rr.created_at, (SELECT MIN(s.at) FROM signals s WHERE s.task_id=rr.review_task_id AND s.verb='done') FROM review_rounds rr JOIN tasks t ON t.id=rr.ship_task_id WHERE (?=0 OR t.project_id=?) AND rr.status='verdict'`, projectID, projectID)
308: 	if err != nil {
309: 		return nil, err
310: 	}
311: 	defer rows.Close()
312: 	var values []int64
313: 	for rows.Next() {
314: 		var started int64
315: 		var settled sql.NullInt64
316: 		if err := rows.Scan(&started, &settled); err != nil {
317: 			return nil, err
318: 		}
319: 		if settled.Valid && settled.Int64 >= started {
320: 			values = append(values, settled.Int64-started)
321: 		}
322: 	}
323: 	if err := rows.Err(); err != nil {
324: 		return nil, err
325: 	}
326: 	if len(values) == 0 {
327: 		return nil, nil
328: 	}
329: 	median := medianInt64(values)
330: 	return &median, nil
331: }
