11: func TestParallelReviewLockDetectsLiveAndAbandonedOwners(t *testing.T) {
12: 	if lockPath := os.Getenv("POSSE_REVIEW_LOCK_CHILD"); lockPath != "" {
13: 		lock, err := inheritedParallelReviewLock(3, lockPath)
14: 		if err != nil {
15: 			t.Fatal(err)
16: 		}
17: 		defer releaseParallelReviewLock(lock)
18: 		ready, done := os.Getenv("POSSE_REVIEW_LOCK_READY"), os.Getenv("POSSE_REVIEW_LOCK_DONE")
19: 		if err := os.WriteFile(ready, []byte("ready"), 0o600); err != nil {
20: 			t.Fatal(err)
21: 		}
22: 		deadline := time.Now().Add(10 * time.Second)
23: 		for time.Now().Before(deadline) {
24: 			if _, err := os.Stat(done); err == nil {
25: 				return
26: 			}
27: 			time.Sleep(10 * time.Millisecond)
28: 		}
29: 		t.Fatal("timed out waiting for parent")
30: 	}
31: 	path := filepath.Join(t.TempDir(), "member.parallel.lock")
32: 	first, busy, err := acquireParallelReviewLock(path)
33: 	if err != nil || busy {
34: 		t.Fatalf("acquire first lock = busy %v, err %v", busy, err)
35: 	}
36: 	if inFlight, err := parallelReviewInFlight(path); err != nil || !inFlight {
37: 		t.Fatalf("active lock = %v, %v; want active", inFlight, err)
38: 	}
39: 	readyPath, donePath := filepath.Join(t.TempDir(), "ready"), filepath.Join(t.TempDir(), "done")
40: 	command := exec.Command(os.Args[0], "-test.run=^TestParallelReviewLockDetectsLiveAndAbandonedOwners$")
41: 	command.Env = append(os.Environ(), "POSSE_REVIEW_LOCK_CHILD="+path, "POSSE_REVIEW_LOCK_READY="+readyPath, "POSSE_REVIEW_LOCK_DONE="+donePath)
42: 	command.ExtraFiles = []*os.File{first}
43: 	if err := command.Start(); err != nil {
44: 		t.Fatal(err)
45: 	}
46: 	if err := first.Close(); err != nil {
47: 		_ = command.Process.Kill()
48: 		_ = command.Wait()
49: 		t.Fatal(err)
50: 	}
51: 	deadline := time.Now().Add(10 * time.Second)
52: 	for time.Now().Before(deadline) {
53: 		if _, err := os.Stat(readyPath); err == nil {
54: 			break
55: 		}
56: 		time.Sleep(10 * time.Millisecond)
57: 	}
58: 	if _, err := os.Stat(readyPath); err != nil {
59: 		_ = command.Process.Kill()
60: 		_ = command.Wait()
61: 		t.Fatalf("child did not acquire inherited lock: %v", err)
62: 	}
